.cr_sp_contract<-function(contract,origin,context){
 c<-contract;.cr_data_required(c,c('contract_id','version','scenario_ids','weights','dates','currency','probability_measure','sampling_design','conditioning','default_timing','prepayment_timing','dilution_treatment','reinvestment_funding','initial_reinvestment_cash'));for(key in c('contract_id','version','currency','conditioning')) .cr_sc_text(c[[key]],key)
 for(key in c('scenario_ids','dates')){x<-unlist(c[[key]],use.names=FALSE);if(!length(x)||anyDuplicated(x)) .cr_error('STRUCTURED_SCENARIOS','Nonempty unique scenario/date axes required')};for(sid in c$scenario_ids) .cr_sc_text(sid,'scenario_id');previous<-origin;for(date in c$dates){if(.cr_data_date(date,'date')<=.cr_data_date(previous,'previous')) .cr_error('STRUCTURED_SCENARIOS','Risk dates strictly increase after pool snapshot');previous<-date};if(length(c$weights)!=length(c$scenario_ids)) .cr_error('STRUCTURED_SCENARIOS','Aligned scenario weights required');weights<-vapply(c$weights,function(w).cr_sc_number(w,'weight',0),0.)
 if(abs(.cr_sc_sum(weights)-1)>1e-12||c$probability_measure!='PHYSICAL'||!(c$sampling_design%in%c('IID_UNWEIGHTED','FIXED_WEIGHTED_SCENARIOS','DEPENDENT_OR_QMC'))) .cr_error('STRUCTURED_SCENARIOS','Normalized physical scenarios and explicit sampling design required');if(c$sampling_design=='IID_UNWEIGHTED'&&any(abs(weights-1/length(weights))>1e-14)) .cr_error('STRUCTURED_SCENARIOS','IID declaration requires uniform weights')
 expected<-list(default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',dilution_treatment='PROPORTIONAL_REMAINING_SCHEDULE',reinvestment_funding='PRINCIPAL_CASH_ONLY');if(any(vapply(names(expected),function(k)c[[k]]!=expected[[k]],TRUE))) .cr_error('STRUCTURED_EVENT_CONTRACT','Explicit supported event and cash reinvestment ordering required');.cr_sc_number(c$initial_reinvestment_cash,'initial_reinvestment_cash',0);ctx<-.cr_result(NULL,'structured.context',context=context)$context;if((!is.null(ctx$currency)&&ctx$currency!=c$currency)||(!is.null(ctx$probability_measure)&&ctx$probability_measure!='PHYSICAL')) .cr_error('TARGET_MISMATCH','Pool scenario currency/measure conflicts with context');expected_context<-list(conditioning=c$conditioning,time_unit='days',horizon=as.numeric(.cr_data_date(tail(c$dates,1)[[1]],'date')-.cr_data_date(origin,'origin')));if(any(vapply(names(expected_context),function(k)!is.null(ctx[[k]])&&!identical(as.character(ctx[[k]]),as.character(expected_context[[k]])),TRUE))) .cr_error('TARGET_MISMATCH','Pool path context must match conditioning and actual calendar-day horizon');list(contract=c,context=ctx)
}
simulate_asset_pool<-function(asset_pool,scenario_contract,obligor_paths,asset_paths,shared_innovations,context=NULL){
 pool<-.cr_sc_checked(asset_pool,'CreditAssetPool');parsed<-.cr_sp_contract(scenario_contract,pool$as_of,context);contract<-parsed$contract;ctx<-parsed$context;if(contract$currency!=pool$profile$currency) .cr_error('TARGET_MISMATCH','Pool and scenario currency differ');sids<-unlist(contract$scenario_ids,use.names=FALSE);risk_dates<-unlist(contract$dates,use.names=FALSE);horizon<-tail(risk_dates,1);assignments<-lapply(c(pool$active_assignments,pool$reinvestment_candidates),function(x)x$assignment);asset_ids<-sort(unique(vapply(assignments,function(a)a$asset_id,'')));tape<-pool$asset_contracts[asset_ids];groups<-sort(unique(vapply(tape,function(a)a$default_group_id,'')))
 for(a in assignments){if(!is.null(a$effective_until)&&a$effective_until<=horizon) .cr_error('STRUCTURED_TRANSFER','Intermediate transfer-out needs explicit sale-price engine; assignment must cover horizon');if(a$effective_from>pool$as_of&&!(a$effective_from%in%risk_dates)) .cr_error('STRUCTURED_CALENDAR','Reinvestment purchases must map to declared risk/payment dates')};for(a in tape)if(any(vapply(a$schedule,function(p)p$date<=horizon&&!(p$date%in%risk_dates),TRUE))) .cr_error('STRUCTURED_CALENDAR','Every contractual payment within horizon must be on event grid')
 keyfn<-function(...) .cr_hash(list(...));innovations<-.cr_data_rows(shared_innovations,'shared_innovations');imap<-list()
 for(row in innovations){.cr_data_required(row,c('scenario_id','date','channel_id','uniform'));.cr_sc_text(row$channel_id,'channel_id');key<-keyfn(row$scenario_id,row$date,row$channel_id);u<-.cr_sc_number(row$uniform,'uniform',0,1);if(!is.null(imap[[key]])||!(row$scenario_id%in%sids)||!(row$date%in%risk_dates)||u==1) .cr_error('STRUCTURED_INNOVATION','Unique scenario/risk-date uniforms in [0,1) required');imap[[key]]<-u}
 used<-character();group_map<-asset_map<-list()
 for(row in .cr_data_rows(obligor_paths,'obligor_paths')){.cr_data_required(row,c('scenario_id','default_group_id','date','conditional_pd','default_channel'));key<-keyfn(row$scenario_id,row$default_group_id,row$date);if(!is.null(group_map[[key]])||!(row$scenario_id%in%sids)||!(row$default_group_id%in%groups)||!(row$date%in%risk_dates)) .cr_error('STRUCTURED_DEFAULT_GROUP','Unique aligned shared default-group paths required');.cr_sc_number(row$conditional_pd,'conditional_pd',0,1);.cr_sc_text(row$default_channel,'default_channel');innovation<-keyfn(row$scenario_id,row$date,row$default_channel);if(is.null(imap[[innovation]])) .cr_error('STRUCTURED_INNOVATION','Missing shared obligor default innovation');used<-union(used,innovation);group_map[[key]]<-row}
 expected<-character();for(s in sids)for(g in groups)for(d in risk_dates)expected<-c(expected,keyfn(s,g,d));if(!setequal(names(group_map),expected)) .cr_error('STRUCTURED_DEFAULT_GROUP','Full group/scenario/date hazard grid required');event_dates<-risk_dates
 for(row in .cr_data_rows(asset_paths,'asset_paths')){
 .cr_data_required(row,c('scenario_id','asset_id','date','conditional_prepayment_probability','prepayment_channel','dilution_fraction','recovery_fraction','recovery_delay_days','recovery_cost','servicing_cost','interest_multiplier','overdue_days','disputed'));key<-keyfn(row$scenario_id,row$asset_id,row$date);if(!is.null(asset_map[[key]])||!(row$scenario_id%in%sids)||!(row$asset_id%in%asset_ids)||!(row$date%in%risk_dates)) .cr_error('STRUCTURED_ASSET_PATH','Unique aligned asset paths required');for(k in c('conditional_prepayment_probability','dilution_fraction','recovery_fraction')) .cr_sc_number(row[[k]],k,0,1);for(k in c('recovery_cost','servicing_cost','interest_multiplier')) .cr_sc_number(row[[k]],k,0);overdue<-.cr_sc_number(row$overdue_days,'overdue_days',0);if(overdue!=floor(overdue)||!is.logical(row$disputed)||length(row$disputed)!=1L||is.na(row$disputed)) .cr_error('STRUCTURED_ASSET_PATH','Dated acquisition eligibility needs integer aging and Boolean dispute state');delay<-.cr_sc_number(row$recovery_delay_days,'recovery_delay_days',0);if(delay!=floor(delay)) .cr_error('STRUCTURED_ASSET_PATH','Integer recovery delay required');recovery_date<-format(.cr_data_date(row$date,'date')+delay,'%Y-%m-%d');if(is.na(recovery_date)||nchar(recovery_date)!=10L) .cr_error('STRUCTURED_CALENDAR','Recovery date outside supported range');if(recovery_date<=horizon)event_dates<-union(event_dates,recovery_date);.cr_sc_text(row$prepayment_channel,'prepayment_channel');innovation<-keyfn(row$scenario_id,row$date,row$prepayment_channel);if(is.null(imap[[innovation]])) .cr_error('STRUCTURED_INNOVATION','Missing prepayment innovation');used<-union(used,innovation);asset_map[[key]]<-row
 }
 expected<-character();for(s in sids)for(a in asset_ids)for(d in risk_dates)expected<-c(expected,keyfn(s,a,d));if(!setequal(names(asset_map),expected)||!setequal(used,names(imap))) .cr_error('STRUCTURED_ASSET_PATH','Complete asset grids and no unused innovation channels required')
 reinvesting<-pool$profile$pool_mode=='REVOLVING';until<-pool$profile$revolving_until;if(!reinvesting&&contract$initial_reinvestment_cash!=0) .cr_error('STRUCTURED_REINVESTMENT','Static pool cannot hold undeclared reinvestment cash');if(reinvesting&&until<=horizon)event_dates<-union(event_dates,until);calendar<-sort(event_dates);asset_results<-group_events<-pool_cashflows<-acquisitions<-endings<-list()
 for(sid in sids){
 balances<-setNames(lapply(asset_ids,function(a)as.numeric(tape[[a]]$principal_balance)),asset_ids);contractual<-balances;status<-setNames(rep(list('PERFORMING'),length(asset_ids)),asset_ids);defaulted<-setNames(rep(list(FALSE),length(groups)),groups);shares<-setNames(lapply(asset_ids,function(a).cr_sc_sum(vapply(Filter(function(x)x$asset_id==a&&x$effective_from<=pool$as_of,assignments),function(x)x$share,0.))),asset_ids);queue<-list();acquired<-vapply(Filter(function(a)a$effective_from<=pool$as_of,assignments),function(a)a$assignment_id,'');reinvestment_cash<-as.numeric(contract$initial_reinvestment_cash);cumulative_credit_loss<-cumulative_dilution<-0
 for(date in calendar){
 opening_reinvestment<-reinvestment_cash;principal_terms<-interest_terms<-servicing_terms<-recovery_terms<-workout_terms<-dilution_terms<-credit_terms<-numeric()
 if(date%in%risk_dates){
 for(group in groups){gp<-group_map[[keyfn(sid,group,date)]];u<-imap[[keyfn(sid,date,gp$default_channel)]];event<-!defaulted[[group]]&&u<gp$conditional_pd;defaulted[[group]]<-defaulted[[group]]||event;group_events[[length(group_events)+1L]]<-list(scenario_id=sid,default_group_id=group,date=date,new_default=event,in_default=defaulted[[group]])}
 for(aid in asset_ids){
 asset<-tape[[aid]];path<-asset_map[[keyfn(sid,aid,date)]];opening<-balances[[aid]];owned<-shares[[aid]];matches<-Filter(function(p)p$date==date,asset$schedule);schedule<-if(length(matches))matches[[1]]else NULL;contractual_due<-if(is.null(schedule))0 else schedule$principal_due;dilution<-scheduled<-prepayment<-default_ead<-interest<-recovery_gross<-recovery_cost<-0;event<-'INACTIVE'
 if(status[[aid]]=='PERFORMING'&&opening>0){
 servicing_terms<-c(servicing_terms,owned*path$servicing_cost);dilution<-opening*path$dilution_fraction;balance<-max(0,opening-dilution);dilution_terms<-c(dilution_terms,owned*dilution);factor<-if(contractual[[aid]]==0)0 else balance/contractual[[aid]]
 if(balance==0){event<-'DILUTED';status[[aid]]<-'DILUTED'}else if(defaulted[[asset$default_group_id]]){
 event<-'DEFAULT';status[[aid]]<-'DEFAULTED';default_ead<-balance;recovery_gross<-default_ead*path$recovery_fraction;recovery_cost<-path$recovery_cost;recovery_date<-format(.cr_data_date(date,'date')+path$recovery_delay_days,'%Y-%m-%d');if(owned>0&&(recovery_gross>0||recovery_cost>0))queue[[length(queue)+1L]]<-list(asset_id=aid,date=recovery_date,gross=owned*recovery_gross,cost=owned*recovery_cost);credit_terms<-c(credit_terms,owned*(default_ead-recovery_gross+recovery_cost));balance<-0
 }else{
 interest<-if(is.null(schedule))0 else schedule$interest_due*factor*path$interest_multiplier
 if(imap[[keyfn(sid,date,path$prepayment_channel)]]<path$conditional_prepayment_probability){event<-'PREPAYMENT';status[[aid]]<-'PREPAID';prepayment<-balance;balance<-0}else{scheduled<-min(balance,contractual_due*factor);balance<-max(0,balance-scheduled);event<-if(balance==0)'MATURED'else'PERFORMING';if(balance==0)status[[aid]]<-'MATURED'}
 }
 balances[[aid]]<-balance;principal_terms<-c(principal_terms,owned*(scheduled+prepayment));interest_terms<-c(interest_terms,owned*interest)
 }
 contractual[[aid]]<-max(0,contractual[[aid]]-contractual_due);residual<-.cr_sc_sum(c(opening,-dilution,-scheduled,-prepayment,-default_ead,-balances[[aid]]));if(abs(residual)>1e-10*max(1,opening)) .cr_error('STRUCTURED_CONSERVATION','Asset principal conservation failed');asset_results[[length(asset_results)+1L]]<-list(scenario_id=sid,asset_id=aid,date=date,ownership_share_before_acquisition=owned,event=event,opening_principal=opening,dilution=dilution,scheduled_principal=scheduled,prepayment_principal=prepayment,default_ead=default_ead,closing_principal=balances[[aid]],interest=interest,modeled_recovery_gross=recovery_gross,modeled_recovery_cost=recovery_cost,principal_conservation_residual=residual)
 }
 }
 remaining_queue<-list();for(flow in queue){if(flow$date==date){recovery_terms<-c(recovery_terms,flow$gross);workout_terms<-c(workout_terms,flow$cost)}else remaining_queue[[length(remaining_queue)+1L]]<-flow};queue<-remaining_queue;principal_cash<-.cr_sc_sum(principal_terms);purchase_terms<-numeric()
 if(reinvesting&&date<until){
 reinvestment_cash<-.cr_sc_sum(c(reinvestment_cash,principal_cash));principal_distributed<-0;purchases<-Filter(function(a)a$effective_from==date&&!(a$assignment_id%in%acquired),assignments);if(length(purchases))purchases<-purchases[order(vapply(purchases,function(a)a$purchase_priority,0.),vapply(purchases,function(a)a$assignment_id,''))]
 for(a in purchases){aid<-a$asset_id;reason<-NULL;if(status[[aid]]!='PERFORMING'||balances[[aid]]<=0)reason<-'ASSET_NO_LONGER_PERFORMING'else if(asset_map[[keyfn(sid,aid,date)]]$overdue_days>pool$profile$maximum_dpd||(asset_map[[keyfn(sid,aid,date)]]$disputed&&pool$profile$exclude_disputed))reason<-'ACQUISITION_ELIGIBILITY_FAILED'else if(a$purchase_price>reinvestment_cash)reason<-'INSUFFICIENT_PRINCIPAL_CASH'
 if(is.null(reason)){reinvestment_cash<-max(0,reinvestment_cash-a$purchase_price);shares[[aid]]<-shares[[aid]]+a$share;if(shares[[aid]]>1+1e-12) .cr_error('STRUCTURED_ASSIGNMENT','Acquired ownership exceeds whole asset');acquired<-c(acquired,a$assignment_id);purchase_terms<-c(purchase_terms,a$purchase_price)}
 acquisitions[[length(acquisitions)+1L]]<-list(scenario_id=sid,assignment_id=a$assignment_id,asset_id=aid,date=date,acquired=is.null(reason),reason=reason,purchase_price=if(is.null(reason))a$purchase_price else 0,acquired_principal=if(is.null(reason))a$share*balances[[aid]]else 0)
 }
 }else{principal_distributed<-.cr_sc_sum(c(principal_cash,reinvestment_cash));reinvestment_cash<-0}
 purchase_cash<-.cr_sc_sum(purchase_terms);cash_residual<-.cr_sc_sum(c(opening_reinvestment,principal_cash,-purchase_cash,-principal_distributed,-reinvestment_cash));if(abs(cash_residual)>1e-10*max(1,opening_reinvestment,principal_cash)) .cr_error('STRUCTURED_CONSERVATION','Reinvestment cash conservation failed');dilution_amount<-.cr_sc_sum(dilution_terms);credit_loss<-.cr_sc_sum(credit_terms);cumulative_dilution<-.cr_sc_sum(c(cumulative_dilution,dilution_amount));cumulative_credit_loss<-.cr_sc_sum(c(cumulative_credit_loss,credit_loss))
 pool_cashflows[[length(pool_cashflows)+1L]]<-list(scenario_id=sid,date=date,principal_collections=principal_cash,principal_available=principal_distributed,interest_available=.cr_sc_sum(interest_terms),recovery_gross=.cr_sc_sum(recovery_terms),workout_cost=.cr_sc_sum(workout_terms),servicing_cost=.cr_sc_sum(servicing_terms),opening_reinvestment_cash=opening_reinvestment,purchase_cash=purchase_cash,closing_reinvestment_cash=reinvestment_cash,closing_performing_principal=.cr_sc_sum(vapply(asset_ids,function(a)shares[[a]]*balances[[a]],0.)),pending_recovery_gross=.cr_sc_sum(vapply(queue,function(q)q$gross,0.)),pending_workout_cost=.cr_sc_sum(vapply(queue,function(q)q$cost,0.)),dilution_loss=dilution_amount,modeled_credit_loss=credit_loss,cumulative_dilution_loss=cumulative_dilution,cumulative_modeled_credit_loss=cumulative_credit_loss,reinvestment_conservation_residual=cash_residual)
 }
 endings[[length(endings)+1L]]<-list(scenario_id=sid,performing_principal=.cr_sc_sum(vapply(asset_ids,function(a)shares[[a]]*balances[[a]],0.)),reinvestment_cash=reinvestment_cash,pending_recoveries=queue,terminal_complete=all(vapply(asset_ids,function(a)shares[[a]]*balances[[a]]==0,TRUE))&&!length(queue)&&reinvestment_cash==0)
 }
 value<-.cr_sc_bound(list(schema_version='1.0',kind='AssetPoolPaths',pool_id=pool$pool_id,pool_hash=pool$sha256,origin=pool$as_of,scenario_contract=contract,scenario_ids=contract$scenario_ids,scenario_weights=contract$weights,dates=as.list(calendar),reference_principal=pool$reference_principal,asset_events=asset_results,group_events=group_events,cashflows=pool_cashflows,acquisitions=acquisitions,ending_states=endings,innovation_hash=.cr_hash(innovations),path_input_hash=.cr_hash(list(obligor_paths=obligor_paths,asset_paths=asset_paths))))
 .cr_result(value,'structured_credit.simulate_asset_pool','pool_cashflows',ctx,diagnostics=.cr_empty_object(),limitations='Initially performing assets with caller-supplied physical conditional hazards; all assets sharing a default group share its absorbing event. Prepayment is conditional on no obligor default and occurs after coupon. Dilution proportionally reduces remaining principal/coupon schedule and remains separate from credit default. Gross recoveries and workout costs are dated separately once; dates between risk endpoints add cash-only grid rows without new hazard draws. Reinvestment acquires only predeclared existing warehouse assets after date payments, using retained principal cash; failed purchase attempts are not silently retried. Servicing is charged on opening performing owned claims. Intermediate legal transfers need explicit sale-price mechanics and are rejected here. End-of-horizon unpaid assets/recoveries remain explicit, not assumed terminal losses or par recoveries.')
}
